1	import { mkdir, readFile, writeFile } from 'node:fs/promises';
2	import { resolve } from 'node:path';
3	import type { Session } from '@dailies/core';
4	import { ingest, NoCheckpointsError } from '@dailies/ingest';
5	import { buildScorecard, safeCommand } from './scorecard';
6	import { runGroundingBenchmark } from './grounding';
7	import { runMutationBenchmark } from './mutation';
8	import { repoKey } from './repoKey';
9	import { unrecognisedTails } from './tails';
10	
11	interface DatasetEntry {
12	  url: string;
13	  maxSessions: number;
14	}
15	
16	// Not the raw error message: git's stderr on a clone/fetch failure can include a local
17	// filesystem path, and a published result never carries freeform text about a failure whose
18	// exact shape wasn't anticipated. A fixed code is all a committed artifact gets.
19	function ingestFailureCode(err: unknown): string {
20	  if (err instanceof NoCheckpointsError) return 'no-checkpoints';
21	  return 'ingest-failed';
22	}
23	
24	// Tails and error text are untrusted content from a real session or a remote git error;
25	// printing them to the operator's own terminal without stripping control/escape characters
26	// would let either inject terminal escape sequences.
27	function consoleSafe(text: string): string {
28	  // eslint-disable-next-line no-control-regex
29	  return text.replace(/[\u0000-\u001f\u007f-\u009f]/g, ' ');
30	}
31	
32	async function main(): Promise<void> {
33	  const dataDir = resolve(process.cwd(), '.dailies');
34	  const datasetPath = resolve(import.meta.dirname, '../datasets/public.json');
35	  const dataset: DatasetEntry[] = JSON.parse(await readFile(datasetPath, 'utf8'));
36	
37	  const sessionsByRepo: { repo: string; session: Session }[] = [];
38	  const allSessions: Session[] = [];
39	  const skipped: { repo: string; reason: string }[] = [];
40	
41	  for (const entry of dataset) {
