    "packages/*/src/**/*.ts",
    "packages/*/src/**/*.tsx",
    "packages/*/test/**/*.ts",
    "eval/src/**/*.ts",
    "eval/test/**/*.ts"
  ]
}
----
import { defineConfig } from 'vitest/config';
export default defineConfig({
