    );
    lines.push('');

    const reasons = Object.entries(mutation.ineligibleReasons ?? {});
    lines.push('### Ineligible runs (version 2)');
    if (reasons.length === 0) {
      lines.push('None.');
    } else {
      for (const [reason, count] of reasons) lines.push(`- ${sanitizeCell(reason)}: ${count}`);
